package id.payu.promotion.adapter.persistence;
import id.payu.promotion.adapter.persistence.entity.PromotionEntity; import id.payu.promotion.domain.model.Promotion; import org.springframework.stereotype.Component;
@Component public class PromotionPersistenceMapper {
 public Promotion toDomain(PromotionEntity e){Promotion p=new Promotion();p.setId(e.getId());p.setVersion(e.getVersion());p.setCode(e.getCode());p.setName(e.getName());p.setDescription(e.getDescription());p.setPromotionType(e.getPromotionType());p.setRewardType(e.getRewardType());p.setRewardValue(e.getRewardValue());p.setMaxRedemptions(e.getMaxRedemptions());p.setRedemptionCount(e.getRedemptionCount());p.setMinTransactionAmount(e.getMinTransactionAmount());p.setMerchantCodes(e.getMerchantCodes());p.setCategoryCodes(e.getCategoryCodes());p.setStatus(e.getStatus());p.setStartDate(e.getStartDate());p.setEndDate(e.getEndDate());p.setCreatedAt(e.getCreatedAt());p.setUpdatedAt(e.getUpdatedAt());return p;}
 public PromotionEntity toEntity(Promotion p){PromotionEntity e=new PromotionEntity();e.setId(p.getId());e.setVersion(p.getVersion());e.setCode(p.getCode());e.setName(p.getName());e.setDescription(p.getDescription());e.setPromotionType(p.getPromotionType());e.setRewardType(p.getRewardType());e.setRewardValue(p.getRewardValue());e.setMaxRedemptions(p.getMaxRedemptions());e.setRedemptionCount(p.getRedemptionCount());e.setMinTransactionAmount(p.getMinTransactionAmount());e.setMerchantCodes(p.getMerchantCodes());e.setCategoryCodes(p.getCategoryCodes());e.setStatus(p.getStatus());e.setStartDate(p.getStartDate());e.setEndDate(p.getEndDate());e.setCreatedAt(p.getCreatedAt());e.setUpdatedAt(p.getUpdatedAt());return e;}
}
